def _pairs(b):
    g = b.grid
    n = 0
    for r in range(4):
        for c in range(2, 6):
            if g[r][c] != 2:
                continue
            for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < 6 and 2 <= cc <= 5 and g[rr][cc] == 2:
                    n += 1
    return n

